<script setup lang="ts">
import { computed, reactive, watch } from 'vue'
import { copyrightModes, copyrightPurposes, isCopyrightTerms, type CopyrightTerms } from '@/api/modules/rights'
const props=defineProps<{modelValue:CopyrightTerms|null;sample?:boolean}>(),emit=defineEmits<{'update:modelValue':[CopyrightTerms|null]}>()
const f=reactive({mode:'',scope:'',territories:'',purposes:[] as string[],terms:''})
const value=computed(()=>({version:'CONTRACT_20261029',mode:f.mode,buyout_price_included:f.mode==='BUYER_OWNERSHIP',license:f.mode==='BUYER_OWNERSHIP'?null:{scope:f.scope,territories:f.territories.split(/[\s,，]+/).filter(Boolean),purposes:f.purposes,perpetual:true,exclusive:false,transferable:false,sublicensable:false,terms_text:f.terms.trim()},personality_rights_retained:true,underlying_assets_excluded:true,third_party_licenses_retained:true}))
watch([value,()=>props.sample],([v])=>emit('update:modelValue',isCopyrightTerms(v)&&(!props.sample||v.mode==='PRODUCER_OWNERSHIP_LICENSE')?v:null),{deep:true})
</script>
<template><section class="supply-card" data-testid="copyright-choice"><h2>成片版权与获准用途</h2><label>本次明确选择 *<select v-model="f.mode" required><option value="">请与客户明确约定后选择</option><option v-for="(label,key) in copyrightModes" :key="key" :value="key" :disabled="sample&&key==='BUYER_OWNERSHIP'">{{label}}</option></select></label><p v-if="f.mode==='BUYER_OWNERSHIP'">本商品价款包含成片版权转让；不包含出镜人的肖像声音权、底层模型或第三方音乐字体版权。</p><template v-if="f.mode==='PRODUCER_OWNERSHIP_LICENSE'"><label>约定许可 *<select v-model="f.scope" required><option value="">请选择</option><option value="PERSONAL_NONCOMMERCIAL">个人非商用</option><option value="AGREED_SCOPE">另行明确约定范围</option></select></label><div class="license-checks"><label v-for="(label,key) in copyrightPurposes" :key="key"><input v-model="f.purposes" type="checkbox" :value="key" :disabled="f.scope==='PERSONAL_NONCOMMERCIAL'&&['COMMERCIAL','RELEASE'].includes(key)">{{label}}</label></div><label>许可地域 *<input v-model="f.territories" placeholder="明确国家代码，例如 CN；全球填写 WORLD" required></label><label>具体使用约定 *<textarea v-model="f.terms" maxlength="8000" required></textarea></label><p>永久、非独家、不可转让、不可再许可。上述用途与地域以确认后的原合同为准。</p></template><p>肖像、声音等人格权仍归本人；底层资产与第三方许可不因本交易转让。人工样片须本人确认当前委托，机构不能代同意。</p><p v-if="f.mode&&!modelValue" class="muted">请补齐一致的用途、地域和条款。个人许可不能勾选商业或发行。</p></section></template>
